const body = $input.all()[0].json.body;

const nom = body.message?.toolCalls?.[0]?.function?.arguments?.nom || "";
const telephone = body.message?.toolCalls?.[0]?.function?.arguments?.telephone || "";
const raison_rappel = body.message?.toolCalls?.[0]?.function?.arguments?.raison_rappel || "";
const meilleur_moment = body.message?.toolCalls?.[0]?.function?.arguments?.meilleur_moment || "";
const toolCallId = body.message?.toolCalls?.[0]?.id || "";

let telClean = telephone.replace(/\D/g, '');
if (telClean.length === 10) telClean = '1' + telClean;
if (!telClean.startsWith('+')) telClean = '+' + telClean;

// Créer un événement dans 1 heure pour rappeler le patient
const now = new Date();
const rappelDate = new Date(now.getTime() + 60 * 60000);
const debut = rappelDate.toISOString();
const fin = new Date(rappelDate.getTime() + 15 * 60000).toISOString();

return [{
 json: {
 nom,
 telephone: telClean,
 raison_rappel,
 meilleur_moment,
 toolCallId,
 debut,
 fin
 }
}];
